/* (10/11) caminar de frente y de espaldas de los tres jefes del coliseo (PixelLab: vista nueva desde la de costado,
   animada y achicada a su altura; pies en y=60). ck_bestias_chibi.js las pasa al coliseo como elite_walk_front, etc. */
(function () {
  const C = window.CK_CHIBI_ARTE && window.CK_CHIBI_ARTE.coliseo; if (!C) return;
  if (C.elite) Object.assign(C.elite, {"walk_front":{"img":"data:image/png;base64,","n":5},"walk_back":{"img":"data:image/png;base64,","n":8}});
  if (C.gorila) Object.assign(C.gorila, {"walk_front":{"img":"data:image/png;base64,","n":8},"walk_back":{"img":"data:image/png;base64,","n":8}});
  if (C.jinete) Object.assign(C.jinete, {"walk_front":{"img":"data:image/png;base64,","n":8},"walk_back":{"img":"data:image/png;base64,","n":8}});
})();

/* (11/11) Gorvak rediseñado más chiquito ("quedó muy grande, rediseñalo más tiny"): todas sus hojas nuevas (PixelLab), con
   carga (windup), escudazo (attack2) y caminar de frente y de espaldas (el escudo al costado, no tapando). Y cargas y
   ataques 2 para los demás jefes: Kragmor y Ulrak (coliseo), Grushak y Garra Negra (estas dos, como animaciones
   sueltas: orc_warlord_windup y werebear_jefe_windup). */
(function () {
  const A = window.CK_CHIBI_ARTE; if (!A || !A.coliseo) return;
  const C = A.coliseo;
  C.elite = {"idle": {"img": "data:image/png;base64,", "n": 4}, "walk": {"img": "data:image/png;base64,", "n": 8}, "attack1": {"img": "data:image/png;base64,", "n": 9}, "salto": {"img": "data:image/png;base64,", "n": 9}, "block": {"img": "data:image/png;base64,", "n": 5}, "death": {"img": "data:image/png;base64,", "n": 9}, "windup": {"img": "data:image/png;base64,", "n": 7}, "attack2": {"img": "data:image/png;base64,", "n": 8}, "walk_front": {"img": "data:image/png;base64,", "n": 8}, "walk_back": {"img": "data:image/png;base64,", "n": 8}};
  Object.assign(C.gorila, {"windup": {"img": "data:image/png;base64,", "n": 7}, "attack2": {"img": "data:image/png;base64,", "n": 9}});
  Object.assign(C.jinete, {"windup": {"img": "data:image/png;base64,", "n": 7}, "attack2": {"img": "data:image/png;base64,", "n": 9}});
  const X = { orc_warlord_windup: {"img": "data:image/png;base64,", "n": 7}, werebear_jefe_windup: {"img": "data:image/png;base64,", "n": 7} };
  window.GAME_ASSETS_BASE64 = window.GAME_ASSETS_BASE64 || {}; window.CK_ANIMS_EXTRA = window.CK_ANIMS_EXTRA || {};
  Object.keys(X).forEach(k => { window.GAME_ASSETS_BASE64[k] = X[k].img; window.CK_ANIMS_EXTRA[k] = X[k].n; });
})();
